# Conditional Workflow Router demo: outcome-driven branching with tracing.
def router(result):
    trace=[]
    if result["ok"]:
        trace.append("success")
        route="store" if result["confidence"]>0.8 else "verify-then-store"
    elif result["error"]=="timeout":
        route="retry-with-backoff"; trace.append("error:timeout")
    else:
        route="escalate"; trace.append("error:"+result["error"])
    trace.append("route:"+route); return route,trace
for r in [{"ok":True,"confidence":0.95},{"ok":True,"confidence":0.4},
          {"ok":False,"error":"timeout"},{"ok":False,"error":"auth"}]:
    print(router(r))

